// SlotFill — The content of a slot: one node, or a list of nodes for list
// slots.
// Exactly one of One and Many is set.
type SlotFill struct {
	One  *Node
	Many []Node
}

// MarshalJSON writes a single value or a list.
func (s SlotFill) MarshalJSON() ([]byte, error) {
	if s.Many != nil {
		return json.Marshal(s.Many)
	}
	return json.Marshal(s.One)
}

// UnmarshalJSON reads a single value or a list.
func (s *SlotFill) UnmarshalJSON(data []byte) error {
	if trimmed := bytes.TrimSpace(data); len(trimmed) > 0 && trimmed[0] == '[' {
		s.One = nil
		return json.Unmarshal(data, &s.Many)
	}
	s.Many = nil
	s.One = new(Node)
	return json.Unmarshal(data, s.One)
}

